-- 103: Wiener Prater from Carter's RCDB screenshots, 2026-10-31.
--   Olympia Looping: the traveling BHS/Schwarzkopf looper (filed under Barth
--     Family). RCDB lists its Prater stays as separate visits (2016, 2025...);
--     Carter: "make olympia looping the 2016 date to current so its still
--     open" - one Prater row, opened 25 Mar 2016, not closed, linked to the
--     Barth Family row as the same ride (one credit). Both get its stats:
--     106.7 ft, 49.7 mph, 4,101.1 ft, 5 loops.
--   Unknown: MACK launched coaster opening Apr 2027 (Liliputbahn), 65.6 ft,
--     1,968.5 ft - capital U like the other Unknowns.
--   Auto BergBahn: wooden kiddie coaster, since 1948 (RCDB: 0 inversions only).
--   Boomerang: Vekoma, 116.5 ft, 47 mph, 935 ft, 3 inv, 1:48, since 1992.
--   Dizzy Mouse: Reverchon spinning mouse, 42.7 ft, 29.1 mph, 1,377.9 ft, 1:30,
--     since 1998.
--   Gesengte Sau (Gerstlauer Bobsled 610/4, 2020), Insider (Maurer spinner,
--     2013; came from Tokyo Dome City's Spinning Coaster Maihime, not a row
--     here), Maskerade (Gerstlauer spinner, 2015), Megablitz (Vekoma custom
--     MK-700, 1994). New: Hochschaubahn, wooden scenic railway since 1950.
-- Safe to run twice.
INSERT INTO coasters (id, name, park, type, manu, model, h, s, l, inv, dur, yr, opened, openedPrec, closed, closedPrec, laps) SELECT (SELECT COALESCE(MAX(id),0)+1 FROM coasters), 'Olympia Looping', 'Wiener Prater', 'Steel', 'BHS', NULL, 106.7, 49.7, 4101.1, 5, NULL, 2016, '2016-03-25', 'day', NULL, NULL, 1 WHERE NOT EXISTS (SELECT 1 FROM coasters WHERE name = 'Olympia Looping' AND park = 'Wiener Prater');
INSERT INTO activity (at, actor, kind, subject, n, detail) SELECT strftime('%Y-%m-%dT%H:%M:%fZ','now'), NULL, 'coaster_added', c.name, NULL, json_object('id', c.id, 'park', c.park) FROM coasters c WHERE c.name = 'Olympia Looping' AND c.park = 'Wiener Prater' AND NOT EXISTS (SELECT 1 FROM activity a WHERE a.kind = 'coaster_added' AND json_extract(a.detail, '$.id') = c.id);
INSERT INTO activity (at, actor, kind, subject, n, detail) SELECT strftime('%Y-%m-%dT%H:%M:%fZ','now'), NULL, 'coaster_edited', name, 4, json_object('id', id, 'fields', json_array('h', 's', 'l', 'inv'), 'via', '103') FROM coasters WHERE name = 'Olympia Looping' AND park = 'Barth Family' AND l IS NULL;
UPDATE coasters SET h = 106.7, s = 49.7, l = 4101.1, inv = 5 WHERE name = 'Olympia Looping' AND park = 'Barth Family' AND l IS NULL;
INSERT OR IGNORE INTO same_ride (coaster, ride) SELECT c.id, h.id FROM coasters c, coasters h WHERE h.name = 'Olympia Looping' AND h.park = 'Barth Family' AND (c.id = h.id OR (c.name = 'Olympia Looping' AND c.park = 'Wiener Prater'));
INSERT INTO activity (at, actor, kind, subject, n, detail) SELECT strftime('%Y-%m-%dT%H:%M:%fZ','now'), NULL, 'same_ride_set', h.name, (SELECT COUNT(*) FROM same_ride s WHERE s.ride = h.id), json_object('ride', h.id, 'at', (SELECT json_group_array(json_object('id', c.id, 'park', c.park, 'name', c.name)) FROM coasters c JOIN same_ride s ON s.coaster = c.id WHERE s.ride = h.id), 'via', '103') FROM coasters h WHERE h.name = 'Olympia Looping' AND h.park = 'Barth Family' AND (SELECT COUNT(*) FROM same_ride s WHERE s.ride = h.id) > 1 AND NOT EXISTS (SELECT 1 FROM activity a WHERE a.kind = 'same_ride_set' AND a.detail LIKE '%"via":"103"%' AND json_extract(a.detail, '$.ride') = h.id);
INSERT INTO coasters (id, name, park, type, manu, model, h, s, l, inv, dur, yr, opened, openedPrec, closed, closedPrec, laps) SELECT (SELECT COALESCE(MAX(id),0)+1 FROM coasters), 'Unknown', 'Wiener Prater', 'Steel', 'MACK Rides', 'MACK Launch', 65.6, NULL, 1968.5, 0, NULL, 2027, '2027-04', 'month', NULL, NULL, 1 WHERE NOT EXISTS (SELECT 1 FROM coasters WHERE name = 'Unknown' AND park = 'Wiener Prater');
INSERT INTO activity (at, actor, kind, subject, n, detail) SELECT strftime('%Y-%m-%dT%H:%M:%fZ','now'), NULL, 'coaster_added', c.name, NULL, json_object('id', c.id, 'park', c.park) FROM coasters c WHERE c.name = 'Unknown' AND c.park = 'Wiener Prater' AND NOT EXISTS (SELECT 1 FROM activity a WHERE a.kind = 'coaster_added' AND json_extract(a.detail, '$.id') = c.id);
INSERT INTO coasters (id, name, park, type, manu, model, h, s, l, inv, dur, yr, opened, openedPrec, closed, closedPrec, laps) SELECT (SELECT COALESCE(MAX(id),0)+1 FROM coasters), 'Auto BergBahn', 'Wiener Prater', 'Wood', NULL, NULL, NULL, NULL, NULL, 0, NULL, 1948, '1948', 'year', NULL, NULL, 1 WHERE NOT EXISTS (SELECT 1 FROM coasters WHERE name = 'Auto BergBahn' AND park = 'Wiener Prater');
